export function animatePixels(source,water,leaves,w,h,t,{waterOn=true,leafOn=true}={}){const dst=new Uint8ClampedArray(source),mask=new Uint8Array(w*h),leafMask=new Uint8Array(w*h);for(const i of water)mask[i]=1;for(const i of leaves)leafMask[i]=1;let writes=0;function sample(ids,amp,period,guard){const phase=t/period*Math.PI*2;for(const i of ids){const x=i%w,y=(i/w)|0,shift=amp*Math.sin(phase+y*.031+x*.007),dx=shift<0?-1:1,j=i+dx,k=i*4,n=j*4,m=Math.abs(shift);if(x+dx<0||x+dx>=w||guard&&!guard[j])continue;for(let c=0;c<3;c++)dst[k+c]=Math.round(source[k+c]*(1-m)+source[n+c]*m);writes++;}}if(waterOn)sample(water,.9,4200,mask);if(leafOn)sample(leaves,.55,3200,leafMask);return{pixels:dst,writes}}
export function nightMix(minutes){const m=((minutes%1440)+1440)%1440;if(m>=1200||m<330)return 1;if(m>=1080)return(m-1080)/120;if(m<450)return 1-(m-330)/120;return 0}
export function lighting(g,row,mix){if(!mix)return;g.save();g.fillStyle=`rgba(18,29,64,${mix*.48})`;g.fillRect(0,0,row.width,row.height);g.globalCompositeOperation='screen';for(const[index,[x,y]]of row.lamps.entries()){const q=g.createRadialGradient(x,y,0,x,y,38);q.addColorStop(0,`rgba(255,190,92,${.25*mix})`);q.addColorStop(1,'rgba(255,190,92,0)');g.fillStyle=q;g.fillRect(x-38,y-38,76,76);g.fillStyle=`rgba(255,215,130,${.22*mix})`;g.beginPath();g.ellipse(x,y,row.downlightIndices?.includes(index)?6:4,row.downlightIndices?.includes(index)?2:9,0,0,Math.PI*2);g.fill()}g.restore()}
